-- =====================================================================================
-- Test parameters ("Includes 31 parameters") + report times for Agilus Diagnostics, Raipur.
-- Source: agilusdiagnostics.com Raipur test pages (18 Nov 2026). Run AFTER agilus_raipur.sql. Safe to re-run.
-- Parameters are stored per lab, because each lab's version of a test can include different parameters.
-- =====================================================================================
alter table lab_tests add column if not exists parameters jsonb;   -- [{"g":"Group name","p":["Param",...]}]
alter table lab_tests add column if not exists param_count int;

update lab_tests set parameters='[{"g": "Blood counts", "p": ["Hemoglobin (Hb)", "Red Blood Cell (RBC) Count", "White Blood Cell (WBC) Count", "Platelet Count"]}, {"g": "RBC & platelet indices", "p": ["Hematocrit (PCV)", "Mean Corpuscular Volume (MCV)", "Mean Corpuscular Hemoglobin (MCH)", "Mean Corpuscular Hemoglobin Concentration (MCHC)", "Red Cell Distribution Width (RDW)", "Mean Platelet Volume (MPV)"]}, {"g": "WBC differential count", "p": ["Neutrophils", "Lymphocytes", "Monocytes", "Eosinophils", "Basophils", "Absolute Neutrophil Count", "Absolute Lymphocyte Count", "Absolute Monocyte Count", "Absolute Eosinophil Count", "Absolute Basophil Count", "Band (stab) Cells", "Metamyelocyte", "Myelocytes", "Promyelocytes", "Blasts"]}, {"g": "Morphology (microscopy)", "p": ["RBC", "WBC", "Platelets", "Impression", "Nucleated RBCs", "Remarks"]}]'::jsonb,param_count=31,turnaround='Same day',updated_at=now()
  where lab_id=(select id from labs where name='Agilus Diagnostics') and test_id=(select id from tests where import_key='hypatho:196');
update lab_tests set parameters='[{"g": "", "p": ["HbA1c", "Estimated Average Glucose (eAG)"]}]'::jsonb,param_count=2,turnaround='Same day',updated_at=now()
  where lab_id=(select id from labs where name='Agilus Diagnostics') and test_id=(select id from tests where import_key='hypatho:281');
